      "code": "#include <future>\n#include <iterator>\n#include <memory>\n#include <semaphore>\n#include <stdexcept>\n#include <vector>\n\nconstexpr int MAX_PARALLEL = 4;\n\nstd::vector<Metric> collectParallel(\n        const std::vector<std::unique_ptr<MetricSource>>& sources) {\n\n    std::counting_semaphore<MAX_PARALLEL> limit(MAX_PARALLEL);\n    std::vector<std::future<std::vector<Metric>>> futures;\n    futures.reserve(sources.size());\n\n    for (const auto& src : sources) {\n        futures.push_back(std::async(std::launch::async,\n            [source = src.get(), &limit] {\n                limit.acquire();\n                struct Release {\n                    std::counting_semaphore<MAX_PARALLEL>& semaphore;\n                    ~Release() noexcept { semaphore.release(); }\n                } release{limit};\n                if (source == nullptr)\n                    throw std::invalid_argument(\"null MetricSource\");\n                return source->collect();\n            }));\n    }\n\n    std::vector<Metric> snapshot;\n    for (std::size_t i = 0; i < futures.size(); ++i) {\n        std::vector<Metric> metrics;\n        try {\n            metrics = futures[i].get();\n        } catch (const std::exception& e) {\n            logSourceFailureNoThrow(i, e.what());\n            continue;\n        } catch (...) {\n            logUnknownSourceFailureNoThrow(i);\n            continue;\n        }\n\n        snapshot.insert(snapshot.end(),\n                        std::make_move_iterator(metrics.begin()),\n                        std::make_move_iterator(metrics.end()));\n    }\n    return snapshot;\n}",
